-- CueTheCashier: vendor buy prices for reagents.
--
-- The base prices come from the game data (VendorPrices.lua, generated by
-- tools/build_vendor_prices.py). The game gives every item a buy price,
-- even ones no vendor sells, so a price is only used for items known to be
-- sold by vendors: the list in VendorPrices.lua plus every reagent you see
-- at a merchant (also reagents missing from the table, since 0.15.0).
--
-- The check (Kim's rule): at a merchant, the price shown has your
-- reputation discount in it (Friendly 0%, Honored 10%, Revered 15%,
-- Exalted 20%). We undo it and compare with the table. If the result is
-- higher than the table, the higher price is saved and used from then on
-- (a lower one means a discount we don't know about, e.g. Forever's legacy
-- system, so it is only logged).
--
-- Saved: CueTheCashierDB.vendorSold[itemID] = true
--        CueTheCashierDB.vendorBuy[itemID]  = base price, when higher than the table
-- Copyright (C) 2026 Kim. Licensed under the GNU GPL v3 or later; see LICENSE.
local _, CM = ...

local Merchant = {}
CM.Merchant = Merchant

-- UnitReaction of the merchant towards you: 6 Honored, 7 Revered, 8 Exalted.
local DISCOUNT = { [6] = 0.10, [7] = 0.15, [8] = 0.20 }
local STANDING = { [4] = "Neutral", [5] = "Friendly", [6] = "Honored", [7] = "Revered", [8] = "Exalted" }

-- Base vendor price (copper per item) for a reagent vendors sell, or nil.
function CM.Data:GetVendorBuyPrice(itemID)
  if not itemID then return nil end
  local sold = (CM.VendorSold and CM.VendorSold[itemID]) or (CueTheCashierDB.vendorSold or {})[itemID]
  if not sold then return nil end
  local learned = (CueTheCashierDB.vendorBuy or {})[itemID]
  local fromData = CM.VendorBuy and CM.VendorBuy[itemID]
  if learned and (not fromData or learned > fromData) then return learned end
  return fromData
end

local function ItemAt(i)
  local id = GetMerchantItemID and GetMerchantItemID(i)
  if not id then return nil end
  local price, quantity, extended
  if C_MerchantFrame and C_MerchantFrame.GetItemInfo then
    local info = C_MerchantFrame.GetItemInfo(i)
    if not info then return nil end
    price, quantity, extended = info.price, info.stackCount, info.hasExtendedCost
  elseif GetMerchantItemInfo then
    local _, _, p, q, _, _, _, ext = GetMerchantItemInfo(i)
    price, quantity, extended = p, q, ext
  end
  if not price or price <= 0 or extended then return nil end
  return id, price / math.max(quantity or 1, 1)
end

function Merchant:Check()
  if not GetMerchantNumItems then return end
  local reaction = UnitReaction and UnitReaction("npc", "player") or 4
  local discount = DISCOUNT[reaction] or 0
  CueTheCashierDB.vendorSold = CueTheCashierDB.vendorSold or {}
  CueTheCashierDB.vendorBuy = CueTheCashierDB.vendorBuy or {}
  for i = 1, GetMerchantNumItems() do
    local id, shown = ItemAt(i)
    local tablePrice = id and CM.VendorBuy and CM.VendorBuy[id]
    -- Reagents the game data doesn't list (new recipes, other skills) are
    -- learned too: anything the game marks as a crafting reagent.
    local reagent = id and not tablePrice and select(17, C_Item.GetItemInfo(id)) == true
    if id and (tablePrice or (CM.VendorSold and CM.VendorSold[id]) or reagent) then
      CueTheCashierDB.vendorSold[id] = true
      local base = shown / (1 - discount)
      local known = CM.Data:GetVendorBuyPrice(id) or tablePrice or 0
      -- Shown prices are whole copper after the discount: allow rounding.
      local slack = math.max(1, known * 0.02)
      if math.abs(base - known) > slack then
        local name = C_Item.GetItemInfo(id) or ("item " .. id)
        CM.Debug(("Vendor price check: %s shows %s each at %s (base %s), table says %s.")
          :format(name, tostring(shown), STANDING[reaction] or tostring(reaction),
            tostring(math.floor(base * 100 + 0.5) / 100), tostring(known)))
        if base > known then
          CueTheCashierDB.vendorBuy[id] = math.floor(base * 100 + 0.5) / 100
        end
      end
    end
  end
end

local function OnMerchant() CM.Try("Merchant check", Merchant.Check, Merchant) end
CM.RegisterEvent(Merchant, "MERCHANT_SHOW", OnMerchant)
CM.RegisterEvent(Merchant, "MERCHANT_UPDATE", OnMerchant)
